CREATE UNIQUE INDEX "users_email_key" ON "users"("email");
CREATE UNIQUE INDEX "users_reviewer_id_key" ON "users"("reviewer_id");
ALTER TABLE "users" ADD CONSTRAINT "users_reviewer_id_fkey"
