);
CREATE UNIQUE INDEX "password_reset_tokens_token_hash_key" ON "password_reset_tokens"("token_hash");
CREATE INDEX "password_reset_tokens_user_id_idx" ON "password_reset_tokens"("user_id");
ALTER TABLE "password_reset_tokens" ADD CONSTRAINT "password_reset_tokens_user_id_fkey"
  FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Note: the `session` table (used by connect-pg-simple for server-side
-- session storage, see src/config/session.ts) is intentionally NOT
-- created here — connect-pg-simple creates it automatically on first
-- connection (createTableIfMissing: true). It has no Prisma model.
